export const DEFAULT_LATCH_PRESET = preservedNoiseWash;
export const DEFAULT_BRASS_PRESET = BRASS_PATCHES[0]; // New Default for Brass
export const DEFAULT_ARP_PRESET = PLUCKED_PATCHES[0]; // Arp Service fallback
