export default TonalityTab;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  // Moved cursorPositionsRef up to be accessible by renderStateRef
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // -- Data Structures --
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  // -- State --
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // -- Handlers --
  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = CENTER_OFFSET - viewportW / 2;
        scrollContainerRef.current.scrollTop = CENTER_OFFSET - viewportH / 2;
      }
  };

  // -- Effects --

  // 1. Generation
  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      globalComplexity: settings.globalComplexity,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    // Debounce generation to allow UI to settle
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));

        // Temporarily zero out depths for hidden limits to prevent generation overhead
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);

        // Filter lines based on hidden limits
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        // Recenter on first load
        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  // 2. Viewport Scaling
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          // Maintain center point relative to content
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;

          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;

          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  // -- Derived State for Rendering --

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      // Manual Latches
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      // Chords
      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    presetId = `chord-${chordId}`; // Simplified for visual lookup
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  // -- Refs for Animation Loop --
  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines: [] as LatticeLine[], 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
      // Note: Harmonic neighbors and brightened lines calc skipped for brevity in this fix step, 
      // can be re-added if perf allows, but ensuring core render is robust first.
  }, [data, settings, visualLatchedNodes, activeLines, effectiveScale, latchMode]);

  // -- Audio Sync --
  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActs = prev.get(nodeId);
              if (!prevActs || !prevActs.some(p => p.mode === act.mode)) {
                   const node = nodes.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId as any, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currActs = current.get(nodeId);
              if (!currActs || !currActs.some(c => c.mode === act.mode)) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  // -- Pointer Handling --
  // cursorPositionsRef is now defined above to fix scope error

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      const grid = spatialGrid;
      for(const key of cells) {
          const nodes = grid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  const dx = x - nx;
                  const dy = y - ny;
                  // Use visual settings for hit area
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size; // Generous hit area
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      // Resume context on interaction
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      // Update Cursor State
      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      // Trigger Logic
      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          // Sustain Logic
          if (latchMode === 1 && isCurrentSustainEnabled) {
               setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                   const next = new Map(prev);
                   const modes = next.get(hitNode.id) || new Map<number, number>();
                   if (modes.has(latchMode)) modes.delete(latchMode);
                   else modes.set(latchMode, Date.now());

                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 
          else if (!isCurrentSustainEnabled || settings.isPitchBendEnabled) {
              // Monophonic/Bend trigger
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const preset = (latchMode === 2) ? 'normal' : 'strum';
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      // Update Cursor Pos for rendering lines
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      // Bend Logic
      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              // Calculate screen Y of the node center relative to viewport
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      // Enter/Exit Logic (Strumming)
      if (hitId !== cursor.hoverNodeId) {
          // Stop previous if purely melodic
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          // Start new
          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;

          // Stop Voices
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          } else if (cursor.hoverNodeId && !isCurrentSustainEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.delete(e.pointerId);
              return next;
          });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  // -- Render Loop --
  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }

      // Sync Viewport
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      // Update Global Bend Ref for visual offset if needed (optional)
      // For now, we assume global bend affects audio/midi only, visuals are static.

      rendererRef.current.render(
          bgLineCanvasRef.current,
          staticCanvasRef.current,
          dynamicCanvasRef.current,
          renderStateRef.current
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  // -- Expose Handle --
  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else {
              setPersistentLatches(prev => {
                  const next = new Map();
                  prev.forEach((map, id) => {
                      const newMap = new Map(map);
                      newMap.delete(mode);
                      if (newMap.size > 0) next.set(id, newMap);
                  });
                  return next;
              });
          }
      },
      centerView: centerScroll,
      increaseDepth: () => {/* Logic handled via parent props for settings update */},
      decreaseDepth: () => {/* Logic handled via parent props */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((map, id) => {
              const n = nodeMap.get(id);
              if (n) map.forEach((_, mode) => res.push({ node: n, mode }));
          });
          return res;
      },
      triggerVisual: (nodeId, active) => {
          setExternalTriggers(prev => {
              const next = new Map(prev);
              if (active) next.set(nodeId, Date.now());
              else next.delete(nodeId);
              return next;
          });
      }
  }));

  // -- Background Logic --
  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) {
              baseStyle.backgroundRepeat = 'repeat';
              baseStyle.backgroundSize = 'auto';
          }
          if (settings.bgImageTintStrength > 0) {
              // Handled via separate overlay or CSS filter if needed, 
              // but simplest is just the image here.
          }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor;
          baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />

             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>

        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// Partch Identities (1-15 including composites 9 and 15 for axes)
const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p];
          if (pRat) {
              for(let i=0; i<Math.abs(val); i++) {
                  originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
              }
          }
      });

      localQueue.push({ coords: [...origin.coords], ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              // @ts-ignore
              const depthLimit = settings.limitDepths[prime] || 0;
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      // Check legacy limitComplexities or generic fallback
                      const compLimit = 1000; 
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Re-map to set to speed up lookups
  const nodeSet = new Set(nodes.map(n => n.id));

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              if (nodeSet.has(targetId)) {
                  const target = nodesMap.get(targetId)!;
                  lines.push({
                      id: `${node.id}-${target.id}`,
                      x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                      limit: prime, sourceId: node.id, targetId: target.id
                  });
              }
          }
      });

      // Octave lines
      const coordKey = node.coords.join(',');
      const octaveTargetId = `${coordKey}:${node.octave + 1}`;
      if (nodeSet.has(octaveTargetId)) {
          const target = nodesMap.get(octaveTargetId)!;
          lines.push({
              id: `${node.id}-${target.id}`,
              x1: node.x, y1: node.y, x2: target.x, y2: target.y,
              limit: 2, sourceId: node.id, targetId: target.id
          });
      }
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 * Uses settings.hiddenLimits to determine which identities (axes) are active.
 * Includes 9 and 15 as distinct identities/axes if enabled.
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Filter identities: Include 1, plus any ODD_IDENTITY not in hiddenLimits
    const activeIdentities = ODD_IDENTITIES.filter(id => id === 1 || !settings.hiddenLimits.includes(id));
    activeIdentities.sort((a,b) => a - b);

    const N = activeIdentities.length;

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout: Rotated Grid
            // x determined by sum of indices (diagonal), y by difference
            const x = (o + u) - (N - 1);
            const y = (o - u);

            const id = `diamond-${o}-${u}`;

            // In Diamond Mode, we spoof limitTop/limitBottom with the Identity values
            // so the visualizer colors them according to the identity (e.g. 9 is yellow, 15 is blue)
            // rather than the mathematical prime limit (which would be 3 for 9, 5 for 15).

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x * 1.0,
                y: y * 0.8,
                limitTop: idOton, 
                limitBottom: idUton,
                maxPrime: Math.max(idOton, idUton), 
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);

            // Connect adjacency
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => modeMap.forEach((_, mode) => modes.add(mode)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId: `chord-${chordId}` });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) resultLines.add(line);
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines, 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.brightenedLines = brightenedLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
  }, [data, settings, visualLatchedNodes, activeLines, brightenedLines, effectiveScale, latchMode]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings = JSON.parse(JSON.stringify(settings));

        // Ensure standard generation respects hidden limits by zeroing depths
        // But for Diamond, generatePartchDiamond handles hidden limits internally
        if (effectiveSettings.layoutApproach !== 'diamond') {
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });
        }

        const result = generateLattice(effectiveSettings);

        // Filter lines to ensure no hidden lines are drawn
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (settings.hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;
          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;
          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;
          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      for(const key of cells) {
          const nodes = spatialGrid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  // Use visual settings for hit area, defaulting to 1 if not set (composite identities)
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size;
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1 && isCurrentSustainEnabled) {
               setPersistentLatches(prev => {
                   const next = new Map(prev);
                   const modes = next.get(hitNode.id) || new Map();
                   if (modes.has(latchMode)) modes.delete(latchMode);
                   else modes.set(latchMode, Date.now());
                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 
          else if (!isCurrentSustainEnabled || settings.isPitchBendEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const preset = (latchMode === 2) ? 'normal' : 'strum';
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      if (hitId !== cursor.hoverNodeId) {
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          } else if (cursor.hoverNodeId && !isCurrentSustainEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          }
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      rendererRef.current.render(bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current, renderStateRef.current);
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else setPersistentLatches(prev => { const next = new Map(); prev.forEach((m, id) => { const nm = new Map(m); nm.delete(mode); if(nm.size > 0) next.set(id, nm); }); return next; });
      },
      centerView: centerScroll,
      increaseDepth: () => {
          const limit = lastTouchedLimitRef.current;
          if(limit) updateSettings(prev => {
              // @ts-ignore
              return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: (prev.limitDepths[limit]||0) + 1 } };
          });
      },
      decreaseDepth: () => {/* impl */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((m, id) => { const n = nodeMap.get(id); if(n) m.forEach((_, mode) => res.push({node: n, mode})); });
          return res;
      },
      triggerVisual: (nodeId, active) => setExternalTriggers(prev => { const next = new Map(prev); if(active) next.set(nodeId, Date.now()); else next.delete(nodeId); return next; })
  }));

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
          pointerEvents: 'none', backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover', backgroundColor: 'black' 
      };
      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) { baseStyle.backgroundRepeat = 'repeat'; baseStyle.backgroundSize = 'auto'; }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor; baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative bg-black" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />
             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>
        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastTouchedLimitRef = useRef<number | null>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const centerScroll = () => {
      if (scrollContainerRef.current) {
          const container = scrollContainerRef.current;
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          container.scrollLeft = CENTER_OFFSET - viewW / 2;
          container.scrollTop = CENTER_OFFSET - viewH / 2;
      }
  };

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => modeMap.forEach((_, mode) => modes.add(mode)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId: `chord-${chordId}` });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) resultLines.add(line);
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines, 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.brightenedLines = brightenedLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
  }, [data, settings, visualLatchedNodes, activeLines, brightenedLines, effectiveScale, latchMode]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings = JSON.parse(JSON.stringify(settings));

        // Ensure standard generation respects hidden limits by zeroing depths
        // But for Diamond, generatePartchDiamond handles hidden limits internally
        if (effectiveSettings.layoutApproach !== 'diamond') {
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });
        }

        const result = generateLattice(effectiveSettings);

        // Filter lines to ensure no hidden lines are drawn
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (settings.hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;
          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;
          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;
          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      for(const key of cells) {
          const nodes = spatialGrid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  // Use visual settings for hit area, defaulting to 1 if not set (composite identities)
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size;
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          lastTouchedLimitRef.current = hitNode.maxPrime;
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1 && isCurrentSustainEnabled) {
               setPersistentLatches(prev => {
                   const next = new Map(prev);
                   const modes: Map<number, number> = next.get(hitNode.id) || new Map<number, number>();
                   if (modes.has(latchMode)) modes.delete(latchMode);
                   else modes.set(latchMode, Date.now());
                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 
          else if (!isCurrentSustainEnabled || settings.isPitchBendEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const preset = (latchMode === 2) ? 'normal' : 'strum';
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      if (hitId !== cursor.hoverNodeId) {
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          } else if (cursor.hoverNodeId && !isCurrentSustainEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          }
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      rendererRef.current.render(bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current, renderStateRef.current);
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else setPersistentLatches(prev => { const next = new Map(); prev.forEach((m, id) => { const nm = new Map(m); nm.delete(mode); if(nm.size > 0) next.set(id, nm); }); return next; });
      },
      centerView: centerScroll,
      increaseDepth: () => {
          const limit = lastTouchedLimitRef.current;
          if(limit) updateSettings(prev => {
              // @ts-ignore
              return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: (prev.limitDepths[limit]||0) + 1 } };
          });
      },
      decreaseDepth: () => {/* impl */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((m, id) => { const n = nodeMap.get(id); if(n) m.forEach((_, mode) => res.push({node: n, mode})); });
          return res;
      },
      triggerVisual: (nodeId, active) => setExternalTriggers(prev => { const next = new Map(prev); if(active) next.set(nodeId, Date.now()); else next.delete(nodeId); return next; })
  }));

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
          pointerEvents: 'none', backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover', backgroundColor: 'black' 
      };
      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) { baseStyle.backgroundRepeat = 'repeat'; baseStyle.backgroundSize = 'auto'; }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor; baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative bg-black" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />
             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>
        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// Partch Identities (1-15 including composites 9 and 15 for axes)
const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p];
          if (pRat) {
              for(let i=0; i<Math.abs(val); i++) {
                  originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
              }
          }
      });

      localQueue.push({ coords: [...origin.coords], ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              // @ts-ignore
              const depthLimit = settings.limitDepths[prime] || 0;
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      // Check legacy limitComplexities or generic fallback
                      const compLimit = 1000; 
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Re-map to set to speed up lookups
  const nodeSet = new Set(nodes.map(n => n.id));

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              if (nodeSet.has(targetId)) {
                  const target = nodesMap.get(targetId)!;
                  lines.push({
                      id: `${node.id}-${target.id}`,
                      x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                      limit: prime, sourceId: node.id, targetId: target.id
                  });
              }
          }
      });

      // Octave lines
      const coordKey = node.coords.join(',');
      const octaveTargetId = `${coordKey}:${node.octave + 1}`;
      if (nodeSet.has(octaveTargetId)) {
          const target = nodesMap.get(octaveTargetId)!;
          lines.push({
              id: `${node.id}-${target.id}`,
              x1: node.x, y1: node.y, x2: target.x, y2: target.y,
              limit: 2, sourceId: node.id, targetId: target.id
          });
      }
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 * Uses settings.hiddenLimits to determine which identities (axes) are active.
 * Includes 9 and 15 as distinct identities/axes if enabled.
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Scale factor to match Lattice projection magnitude (Virtual Pixels per Step)
    const GRID_SCALE = 120; 

    // Filter identities: Include 1, plus any ODD_IDENTITY not in hiddenLimits
    // This creates a dense or sparse diamond based on active buttons
    const activeIdentities = ODD_IDENTITIES.filter(id => id === 1 || !settings.hiddenLimits.includes(id));
    activeIdentities.sort((a,b) => a - b);

    const N = activeIdentities.length;

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout: Rotated Grid
            // x determined by sum of indices (diagonal), y by difference
            const x = ((o + u) - (N - 1)) * GRID_SCALE;
            const y = (o - u) * GRID_SCALE;

            const id = `diamond-${o}-${u}`;

            // In Diamond Mode, we spoof limitTop/limitBottom with the Identity values
            // so the visualizer colors them according to the identity (e.g. 9 is yellow, 15 is blue)
            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x,
                y,
                limitTop: idOton, 
                limitBottom: idUton,
                maxPrime: Math.max(idOton, idUton), 
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);

            // Connect adjacency
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastTouchedLimitRef = useRef<number | null>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const centerScroll = () => {
      if (scrollContainerRef.current) {
          const container = scrollContainerRef.current;
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          container.scrollLeft = CENTER_OFFSET - viewW / 2;
          container.scrollTop = CENTER_OFFSET - viewH / 2;
      }
  };

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => modeMap.forEach((_, mode) => modes.add(mode)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId: `chord-${chordId}` });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) resultLines.add(line);
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines, 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.brightenedLines = brightenedLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
  }, [data, settings, visualLatchedNodes, activeLines, brightenedLines, effectiveScale, latchMode]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings = JSON.parse(JSON.stringify(settings));

        // Ensure standard generation respects hidden limits by zeroing depths
        // But for Diamond, generatePartchDiamond handles hidden limits internally
        if (effectiveSettings.layoutApproach !== 'diamond') {
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });
        }

        const result = generateLattice(effectiveSettings);

        // Filter lines to ensure no hidden lines are drawn
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (settings.hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;
          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;
          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;
          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      for(const key of cells) {
          const nodes = spatialGrid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  // Use visual settings for hit area, defaulting to 1 if not set (composite identities)
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size;
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          lastTouchedLimitRef.current = hitNode.maxPrime;
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1 && isCurrentSustainEnabled) {
               setPersistentLatches(prev => {
                   const next = new Map<string, Map<number, number>>(prev);
                   const existingModes = next.get(hitNode.id);
                   // Clone the existing map to avoid mutating state
                   const modes = existingModes ? new Map<number, number>(existingModes) : new Map<number, number>();

                   if (modes.has(latchMode)) modes.delete(latchMode);
                   else modes.set(latchMode, Date.now());

                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 
          else if (!isCurrentSustainEnabled || settings.isPitchBendEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const preset = (latchMode === 2) ? 'normal' : 'strum';
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      if (hitId !== cursor.hoverNodeId) {
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          } else if (cursor.hoverNodeId && !isCurrentSustainEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          }
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      rendererRef.current.render(bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current, renderStateRef.current);
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else setPersistentLatches(prev => { 
              const next = new Map<string, Map<number, number>>(); 
              prev.forEach((m, id) => { 
                  const nm = new Map<number, number>(m); 
                  nm.delete(mode); 
                  if(nm.size > 0) next.set(id, nm); 
              }); 
              return next; 
          });
      },
      centerView: centerScroll,
      increaseDepth: () => {
          const limit = lastTouchedLimitRef.current;
          if(limit) updateSettings(prev => {
              // @ts-ignore
              return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: (prev.limitDepths[limit]||0) + 1 } };
          });
      },
      decreaseDepth: () => {/* impl */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((m, id) => { const n = nodeMap.get(id); if(n) m.forEach((_, mode) => res.push({node: n, mode})); });
          return res;
      },
      triggerVisual: (nodeId, active) => setExternalTriggers(prev => { const next = new Map(prev); if(active) next.set(nodeId, Date.now()); else next.delete(nodeId); return next; })
  }));

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
          pointerEvents: 'none', backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover', backgroundColor: 'black' 
      };
      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) { baseStyle.backgroundRepeat = 'repeat'; baseStyle.backgroundSize = 'auto'; }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor; baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative bg-black" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />
             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>
        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// Partch Identities (1-15 including composites 9 and 15 for axes)
const ODD_IDENTITIES = [1, 3, 5, 7, 9, 11, 13, 15];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p];
          if (pRat) {
              for(let i=0; i<Math.abs(val); i++) {
                  originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
              }
          }
      });

      localQueue.push({ coords: [...origin.coords], ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 1200;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              // @ts-ignore
              const depthLimit = settings.limitDepths[prime] || 0;
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      // @ts-ignore
                      // Check legacy limitComplexities or generic fallback
                      const compLimit = 1000; 
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Re-map to set to speed up lookups
  const nodeSet = new Set(nodes.map(n => n.id));

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              if (nodeSet.has(targetId)) {
                  const target = nodesMap.get(targetId)!;
                  lines.push({
                      id: `${node.id}-${target.id}`,
                      x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                      limit: prime, sourceId: node.id, targetId: target.id
                  });
              }
          }
      });

      // Octave lines
      const coordKey = node.coords.join(',');
      const octaveTargetId = `${coordKey}:${node.octave + 1}`;
      if (nodeSet.has(octaveTargetId)) {
          const target = nodesMap.get(octaveTargetId)!;
          lines.push({
              id: `${node.id}-${target.id}`,
              x1: node.x, y1: node.y, x2: target.x, y2: target.y,
              limit: 2, sourceId: node.id, targetId: target.id
          });
      }
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 * Uses settings.hiddenLimits to determine which identities (axes) are active.
 * Includes 9 and 15 as distinct identities/axes if enabled.
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Scale factor to match Lattice projection magnitude (Virtual Pixels per Step)
    const GRID_SCALE = 120; 

    // Filter identities: Include 1, plus any ODD_IDENTITY not in hiddenLimits
    // This creates a dense or sparse diamond based on active buttons
    const activeIdentities = ODD_IDENTITIES.filter(id => id === 1 || !settings.hiddenLimits.includes(id));
    activeIdentities.sort((a,b) => a - b);

    const N = activeIdentities.length;

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Layout: Rotated Grid
            // x determined by sum of indices (diagonal), y by difference
            const x = ((o + u) - (N - 1)) * GRID_SCALE;
            const y = (o - u) * GRID_SCALE;

            const id = `diamond-${o}-${u}`;

            // In Diamond Mode, we spoof limitTop/limitBottom with the Identity values
            // so the visualizer colors them according to the identity (e.g. 9 is yellow, 15 is blue)
            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x,
                y,
                limitTop: idOton, 
                limitBottom: idUton,
                maxPrime: Math.max(idOton, idUton), 
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);

            // Connect adjacency
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastTouchedLimitRef = useRef<number | null>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const adjacencyMap = useMemo(() => {
      const map = new Map<string, { target: string, limit: number }[]>();
      data.lines.forEach(line => {
          if (!map.has(line.sourceId)) map.set(line.sourceId, []);
          if (!map.has(line.targetId)) map.set(line.targetId, []);
          map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
          map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
      });
      return map;
  }, [data.lines]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const centerScroll = () => {
      if (scrollContainerRef.current) {
          const container = scrollContainerRef.current;
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          container.scrollLeft = CENTER_OFFSET - viewW / 2;
          container.scrollTop = CENTER_OFFSET - viewH / 2;
      }
  };

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => modeMap.forEach((_, mode) => modes.add(mode)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                }
                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId: `chord-${chordId}` });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) resultLines.add(line);
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines, 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.brightenedLines = brightenedLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
  }, [data, settings, visualLatchedNodes, activeLines, brightenedLines, effectiveScale, latchMode]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings = JSON.parse(JSON.stringify(settings));

        // Ensure standard generation respects hidden limits by zeroing depths
        // But for Diamond, generatePartchDiamond handles hidden limits internally
        if (effectiveSettings.layoutApproach !== 'diamond') {
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });
        }

        const result = generateLattice(effectiveSettings);

        // Filter lines to ensure no hidden lines are drawn
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (settings.hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;
          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;
          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;
          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      for(const key of cells) {
          const nodes = spatialGrid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  // Use visual settings for hit area, defaulting to 1 if not set (composite identities)
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size;
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          lastTouchedLimitRef.current = hitNode.maxPrime;
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1 && isCurrentSustainEnabled) {
               setPersistentLatches(prev => {
                   const next = new Map<string, Map<number, number>>(prev);
                   const existingModes = next.get(hitNode.id);
                   const modes = existingModes ? new Map<number, number>(existingModes) : new Map<number, number>();

                   if (modes.has(latchMode)) modes.delete(latchMode);
                   else modes.set(latchMode, Date.now());

                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 
          else if (!isCurrentSustainEnabled || settings.isPitchBendEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const preset = (latchMode === 2) ? 'normal' : 'strum';
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      if (hitId !== cursor.hoverNodeId) {
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          } else if (cursor.hoverNodeId && !isCurrentSustainEnabled) {
              const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(vid);
              if (settings.midiEnabled) midiService.noteOff(vid);
          }
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      rendererRef.current.render(bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current, renderStateRef.current);
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else setPersistentLatches(prev => { 
              const next = new Map<string, Map<number, number>>(); 
              prev.forEach((m, id) => { 
                  const nm = new Map<number, number>(m); 
                  nm.delete(mode); 
                  if(nm.size > 0) next.set(id, nm); 
              }); 
              return next; 
          });
      },
      centerView: centerScroll,
      increaseDepth: () => {
          const limit = lastTouchedLimitRef.current;
          if(limit) updateSettings(prev => {
              // @ts-ignore
              return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: (prev.limitDepths[limit]||0) + 1 } };
          });
      },
      decreaseDepth: () => {/* impl */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((m, id) => { const n = nodeMap.get(id); if(n) m.forEach((_, mode) => res.push({node: n, mode})); });
          return res;
      },
      triggerVisual: (nodeId, active) => setExternalTriggers(prev => { const next = new Map(prev); if(active) next.set(nodeId, Date.now()); else next.delete(nodeId); return next; })
  }));

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
          pointerEvents: 'none', backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover', backgroundColor: 'black' 
      };
      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) { baseStyle.backgroundRepeat = 'repeat'; baseStyle.backgroundSize = 'auto'; }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor; baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative bg-black" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />
             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>
        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void;
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const GRID_CELL_SIZE = 100; 
const VIRTUAL_SIZE = 40000; 
const CENTER_OFFSET = VIRTUAL_SIZE / 2;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const lastTouchedLimitRef = useRef<number | null>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + CENTER_OFFSET;
          const y = node.y * spacing + CENTER_OFFSET;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  const centerScroll = () => {
      if (scrollContainerRef.current) {
          const container = scrollContainerRef.current;
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          container.scrollLeft = CENTER_OFFSET - viewW / 2;
          container.scrollTop = CENTER_OFFSET - viewH / 2;
      }
  };

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => modeMap.forEach((_, mode) => modes.add(mode)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  const getVoiceTypeForMode = (mode: number): string => {
      switch(mode) {
          case 1: return 'latch'; // Drone
          case 2: return 'normal'; // Strings
          case 3: return 'strum'; // Plucked
          case 4: return 'brass'; // Brass
          default: return 'normal';
      }
  };

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();
      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              activations.push({ mode, timestamp, presetId: getVoiceTypeForMode(mode) });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                // Attempt to map back string modes to numbers if stored
                if (n.voiceMode === 'latch') mode = 1;
                else if (n.voiceMode === 'normal') mode = 2;
                else if (n.voiceMode === 'strum') mode = 3;
                else if (n.voiceMode === 'brass') mode = 4;

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId: `chord-${chordId}` });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              const list = visual.get(cursor.hoverNodeId) || [];
              // Use current latchMode for cursor visual
              list.push({ mode: latchMode, timestamp: Date.now(), presetId: 'cursor' });
              visual.set(cursor.hoverNodeId, list);
          }
      });

      externalTriggers.forEach((timestamp, nodeId) => {
          const list = visual.get(nodeId) || [];
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
          visual.set(nodeId, list);
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, externalTriggers, latchMode]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) resultLines.add(line);
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const renderStateRef = useRef({
      data, settings, visualLatchedNodes, activeLines, brightenedLines, 
      harmonicNeighbors: new Map(), activeCursors, cursorPositions: cursorPositionsRef.current,
      nodeTriggerHistory: nodeTriggerHistory.current, globalBend: 0, effectiveScale, 
      centerOffset: CENTER_OFFSET, view: { x: 0, y: 0, w: 100, h: 100 }, time: 0, latchMode
  });

  useEffect(() => {
      renderStateRef.current.data = data;
      renderStateRef.current.settings = settings;
      renderStateRef.current.visualLatchedNodes = visualLatchedNodes;
      renderStateRef.current.activeLines = activeLines;
      renderStateRef.current.brightenedLines = brightenedLines;
      renderStateRef.current.effectiveScale = effectiveScale;
      renderStateRef.current.latchMode = latchMode;
  }, [data, settings, visualLatchedNodes, activeLines, brightenedLines, effectiveScale, latchMode]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      depths: settings.limitDepths,
      hidden: settings.hiddenLimits,
      ratio: settings.latticeAspectRatio,
      skin: settings.activeSkin
  }), [settings]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings = JSON.parse(JSON.stringify(settings));

        // Ensure standard generation respects hidden limits by zeroing depths
        // But for Diamond, generatePartchDiamond handles hidden limits internally
        if (effectiveSettings.layoutApproach !== 'diamond') {
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });
        }

        const result = generateLattice(effectiveSettings);

        // Filter lines to ensure no hidden lines are drawn
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (settings.hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);

        if (isInitialLoad) {
            requestAnimationFrame(centerScroll);
            setIsInitialLoad(false);
        }
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;
      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const oldSpacing = settings.buttonSpacingScale * oldScale;
          const newSpacing = settings.buttonSpacingScale * newScale;
          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;
          const centerX = (currentScrollLeft + viewW / 2) - CENTER_OFFSET;
          const centerY = (currentScrollTop + viewH / 2) - CENTER_OFFSET;
          const normX = centerX / oldSpacing;
          const normY = centerY / oldSpacing;
          container.scrollLeft = (normX * newSpacing + CENTER_OFFSET) - viewW / 2;
          container.scrollTop = (normY * newSpacing + CENTER_OFFSET) - viewH / 2;
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, settings.buttonSpacingScale]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = clientX - rect.left + scrollContainerRef.current.scrollLeft;
      const y = clientY - rect.top + scrollContainerRef.current.scrollTop;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];

      for(const key of cells) {
          const nodes = spatialGrid.get(key);
          if (nodes) {
              for (const node of nodes) {
                  const nx = node.x * spacing + CENTER_OFFSET;
                  const ny = node.y * spacing + CENTER_OFFSET;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * settings.latchedZoomScale * vis.size;
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      if (audioEngine) audioEngine.resume();

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              originNodeId: nodeId,
              hoverNodeId: nodeId,
              hasMoved: false,
              interactionLockedNodeId: null
          });
          return next;
      });
      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      if (hitNode) {
          nodeTriggerHistory.current.set(hitNode.id, Date.now());
          onLimitInteraction(hitNode.maxPrime);
          lastTouchedLimitRef.current = hitNode.maxPrime;
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          const voiceType = getVoiceTypeForMode(latchMode);

          // Drone Mode (1) behaves as a latch toggle
          // Sustain Mode (isCurrentSustainEnabled) also behaves as a latch toggle for other instruments
          if (latchMode === 1 || isCurrentSustainEnabled) {
               setPersistentLatches(prev => {
                   const next = new Map<string, Map<number, number>>(prev);
                   const existingModes = next.get(hitNode.id);
                   const modes = existingModes ? new Map<number, number>(existingModes) : new Map<number, number>();

                   if (modes.has(latchMode)) {
                       // Toggle Off
                       modes.delete(latchMode);
                       // Stop audio if untoggled
                       audioEngine.stopVoice(`node-${hitNode.id}`); // This might need refinement if using granular IDs
                   } else {
                       // Toggle On
                       modes.set(latchMode, Date.now());
                   }

                   if (modes.size > 0) next.set(hitNode.id, modes);
                   else next.delete(hitNode.id);
                   return next;
               });
          } 

          // Momentary Play (If not sustaining/latching)
          if (!isCurrentSustainEnabled && latchMode !== 1) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, voiceType);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursors.has(e.pointerId)) return;
      const cursor = activeCursors.get(e.pointerId)!;

      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          cursorPositionsRef.current.set(e.pointerId, { 
              x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
              y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
          });
      }

      // Pitch Bend Logic
      if (settings.isPitchBendEnabled && cursor.originNodeId) {
          const node = nodeMap.get(cursor.originNodeId);
          if (node && scrollContainerRef.current) {
              const r = scrollContainerRef.current.getBoundingClientRect();
              const spacing = settings.buttonSpacingScale * effectiveScale;
              const nodeScreenY = (node.y * spacing + CENTER_OFFSET) - scrollContainerRef.current.scrollTop + r.top;
              const deltaY = e.clientY - nodeScreenY;

              const ratio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * effectiveScale);
              const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;

              audioEngine.glideVoice(voiceId, node.ratio * ratio, settings.baseFrequency);
              if (settings.midiEnabled) midiService.pitchBend(voiceId, node.ratio * ratio, settings.baseFrequency, settings.midiPitchBendRange);
          }
      }

      if (hitId !== cursor.hoverNodeId) {
          // Stop old momentary note if sliding off
          if (cursor.hoverNodeId && !settings.isPitchBendEnabled && !isCurrentSustainEnabled && latchMode !== 1) {
              const oldId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
              audioEngine.stopVoice(oldId);
              if (settings.midiEnabled) midiService.noteOff(oldId);
          }

          // Trigger new note if sliding onto new node (Glissando / Strum)
          if (hitNode && !settings.isPitchBendEnabled && !isCurrentSustainEnabled && latchMode !== 1) {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              const voiceType = getVoiceTypeForMode(latchMode);

              // For Plucked/Strum mode (3), we might want a 'strum' preset, which is default. 
              // But if LatchMode is 4 (Brass), we must use 'brass'.
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, voiceType);
              if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              nodeTriggerHistory.current.set(hitNode.id, Date.now());
          }

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { ...cursor, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursors.has(e.pointerId)) {
          const cursor = activeCursors.get(e.pointerId)!;

          // Stop momentary notes on release
          if (!isCurrentSustainEnabled && latchMode !== 1) {
              if (cursor.originNodeId && settings.isPitchBendEnabled) {
                  const vid = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                  audioEngine.stopVoice(vid);
                  if (settings.midiEnabled) midiService.noteOff(vid);
              } else if (cursor.hoverNodeId) {
                  const vid = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                  audioEngine.stopVoice(vid);
                  if (settings.midiEnabled) midiService.noteOff(vid);
              }
          }

          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
          cursorPositionsRef.current.delete(e.pointerId);
      }
  };

  const render = (time: number) => {
      if (!bgLineCanvasRef.current || !staticCanvasRef.current || !dynamicCanvasRef.current || !scrollContainerRef.current) {
          animationFrameRef.current = requestAnimationFrame(render);
          return;
      }
      const scroller = scrollContainerRef.current;
      renderStateRef.current.view = { x: scroller.scrollLeft, y: scroller.scrollTop, w: scroller.clientWidth, h: scroller.clientHeight };
      renderStateRef.current.time = time;

      rendererRef.current.render(bgLineCanvasRef.current, staticCanvasRef.current, dynamicCanvasRef.current, renderStateRef.current);
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
      animationFrameRef.current = requestAnimationFrame(render);
      return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  useImperativeHandle(ref, () => ({
      clearLatches: (mode) => {
          if (mode === undefined) setPersistentLatches(new Map());
          else setPersistentLatches(prev => { 
              const next = new Map<string, Map<number, number>>(); 
              prev.forEach((m, id) => { 
                  const nm = new Map<number, number>(m); 
                  nm.delete(mode); 
                  if(nm.size > 0) next.set(id, nm); 
              }); 
              return next; 
          });
      },
      centerView: centerScroll,
      increaseDepth: () => {
          const limit = lastTouchedLimitRef.current;
          if(limit) updateSettings(prev => {
              // @ts-ignore
              return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: (prev.limitDepths[limit]||0) + 1 } };
          });
      },
      decreaseDepth: () => {/* impl */},
      getLatchedNodes: () => {
          const res: { node: LatticeNode, mode: number }[] = [];
          persistentLatches.forEach((m, id) => { const n = nodeMap.get(id); if(n) m.forEach((_, mode) => res.push({node: n, mode})); });
          return res;
      },
      triggerVisual: (nodeId, active) => setExternalTriggers(prev => { const next = new Map(prev); if(active) next.set(nodeId, Date.now()); else next.delete(nodeId); return next; })
  }));

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
          pointerEvents: 'none', backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover', backgroundColor: 'black' 
      };
      if (mode === 'gradient') {
          const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
          const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
          baseStyle.backgroundImage = `${type}(${direction} ${settings.gradientColorStart}, ${settings.gradientColorEnd})`;
          baseStyle.backgroundColor = 'transparent';
      } else if (mode === 'image' && settings.backgroundImageData) {
          baseStyle.backgroundImage = `url("${settings.backgroundImageData}")`;
          if (settings.backgroundTiling) { baseStyle.backgroundRepeat = 'repeat'; baseStyle.backgroundSize = 'auto'; }
      } else if (mode === 'solid') {
          baseStyle.backgroundColor = settings.solidColor; baseStyle.backgroundImage = 'none';
      }
      return baseStyle;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative bg-black" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             <div style={getBackgroundStyles()} className="absolute inset-0 w-full h-full z-0" />
             <div ref={wrapperRef} className="relative w-full h-full z-10">
                <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
                <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
                {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
             </div>
        </div>
        <div style={{ width: VIRTUAL_SIZE, height: VIRTUAL_SIZE }} className="relative z-[-1]" />
    </div>
  );
});

export default React.memo(TonalityDiamond);
